  inset:0 !important;
  width:auto !important; height:auto !important;
  margin:0 !important; padding:0 !important;
  opacity:0 !important;
  z-index:1 !important;
}
.voice-play-btn{ position:relative; z-index:2; }

/* 5. 「语音识别」卡片 */
.voice-transcription{
