  height: 100% !important;
  opacity: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
  z-index: 2 !important;
}

.msg-translation-detached {
  display: block !important;
  margin-top: 3px !important;
  margin-bottom: -15px !important;
