  --voice-them-color:#333333; --voice-them-bar-active:#333333; --voice-them-bar-inactive:rgba(51,51,51,.3);
}

/* ===== 对方输入中：标题显示逐字跳动的「对方正在输入中...」 ===== */
.nuo-typing-indicator{
